INSERT INTO `products` VALUES (1,1,'Pin Lithium LFP 48V 460Ah','pin-lithium-lfp-48v-200ah','IP15PRO-128','Pin lithium sắt phosphate hiệu suất cao cho xe nâng','<p>Pin Lithium LFP 48V 460Ah l&agrave; giải ph&aacute;p ho&agrave;n hảo cho xe n&acirc;ng điện với nhiều ưu điểm vượt trội:</p>\r\n<ul>\r\n<li>Tuổi thọ cao: 3000+ chu kỳ sạc</li>\r\n<li>An to&agrave;n tuyệt đối với c&ocirc;ng nghệ LFP</li>\r\n<li>Sạc nhanh trong 2-3 giờ</li>\r\n<li>Bảo h&agrave;nh 3 năm</li>\r\n</ul>','photos/1/z7487363940596_100c0cac5144f453a50b716711f71b9c.jpg','Bán chạy',NULL,NULL,1,0,1,1,NULL,NULL,'2026-01-27 04:35:06','2026-02-06 11:03:41',NULL),(2,1,'Pin Lithium LFP 80V 460Ah','pin-lithium-lfp-80v-300ah',NULL,'Pin lithium công suất lớn cho xe nâng hạng nặng','<p>Pin Lithium LFP 80V 460 Ah được thiết kế cho c&aacute;c xe n&acirc;ng hng nặng trong m&ocirc;i trường c&ocirc;ng nghiệp khắc nghiệt.</p>','photos/1/z7487363940596_100c0cac5144f453a50b716711f71b9c.jpg','Giảm giá',NULL,NULL,1,0,2,1,NULL,NULL,'2026-01-27 04:35:06','2026-01-31 03:25:47',NULL),(3,1,'Pin Lithium LFP 48V 560Ah','pin-lithium-lfp-24v-100ah',NULL,'Pin lithium nhỏ gọn cho xe nâng điện 2 tấn - 3,5 tấn','<p>D&ograve;ng pin lithium nhỏ gọn ph&ugrave; hợp cho xe n&acirc;ng tay điện v&agrave; c&aacute;c thiết bị vận chuyển nhẹ.</p>','photos/1/z7487363940596_100c0cac5144f453a50b716711f71b9c.jpg',NULL,NULL,NULL,1,0,3,1,NULL,NULL,'2026-01-27 04:35:06','2026-02-04 01:08:43',NULL),(4,2,'Camera AI 360° cho xe nâng – Phiên bản tiêu chuẩn','he-thong-luu-tru-10kwh',NULL,'Hệ thống camera AI 360° hỗ trợ phát hiện người và vật cản xung quanh xe nâng, cảnh báo an toàn theo thời gian thực, giảm tai nạn và điểm mù khi vận hành trong nhà xưởng, kho bãi.','<h3 data-start=\"517\" data-end=\"570\">Camera AI 360&deg; cho xe n&acirc;ng &ndash; Phi&ecirc;n bản ti&ecirc;u chuẩn</h3>\r\n<p data-start=\"572\" data-end=\"846\">Camera AI 360&deg; l&agrave; hệ thống <strong data-start=\"599\" data-end=\"630\">gi&aacute;m s&aacute;t an to&agrave;n th&ocirc;ng minh</strong> d&agrave;nh cho xe n&acirc;ng điện v&agrave; xe n&acirc;ng dầu. Thiết bị sử dụng <strong data-start=\"686\" data-end=\"733\">c&ocirc;ng nghệ AI nhận diện con người v&agrave; vật cản</strong>, kết hợp 4 camera g&oacute;c rộng tạo h&igrave;nh ảnh to&agrave;n cảnh 360&deg;, gi&uacute;p người l&aacute;i quan s&aacute;t đầy đủ m&ocirc;i trường xung quanh xe.</p>\r\n<p data-start=\"848\" data-end=\"1025\">Hệ thống ph&aacute;t cảnh b&aacute;o <strong data-start=\"871\" data-end=\"915\">h&igrave;nh ảnh v&agrave; &acirc;m thanh theo thời gian thực</strong> khi ph&aacute;t hiện nguy cơ, g&oacute;p phần giảm tai nạn, va chạm v&agrave; n&acirc;ng cao hiệu quả vận h&agrave;nh trong kho b&atilde;i, nh&agrave; xưởng.</p>\r\n<hr data-start=\"1027\" data-end=\"1030\">\r\n<h3 data-start=\"1032\" data-end=\"1064\">⚙️ Th&ocirc;ng số &amp; cấu h&igrave;nh ch&iacute;nh</h3>\r\n<ul data-start=\"1065\" data-end=\"1276\">\r\n<li data-start=\"1065\" data-end=\"1099\">\r\n<p data-start=\"1067\" data-end=\"1099\">G&oacute;c quan s&aacute;t: <strong data-start=\"1081\" data-end=\"1099\">360&deg; to&agrave;n cảnh</strong></p>\r\n</li>\r\n<li data-start=\"1100\" data-end=\"1133\">\r\n<p data-start=\"1102\" data-end=\"1133\">Camera: 4 mắt camera g&oacute;c rộng</p>\r\n</li>\r\n<li data-start=\"1134\" data-end=\"1177\">\r\n<p data-start=\"1136\" data-end=\"1177\">Chức năng AI: Nhận diện người / vật cản</p>\r\n</li>\r\n<li data-start=\"1178\" data-end=\"1220\">\r\n<p data-start=\"1180\" data-end=\"1220\">Cảnh b&aacute;o: &Acirc;m thanh + hiển thị m&agrave;n h&igrave;nh</p>\r\n</li>\r\n<li data-start=\"1221\" data-end=\"1276\">\r\n<p data-start=\"1223\" data-end=\"1276\">Ứng dụng: Xe n&acirc;ng điện, xe n&acirc;ng dầu, m&aacute;y c&ocirc;ng tr&igrave;nh</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1278\" data-end=\"1281\">\r\n<h3 data-start=\"1283\" data-end=\"1308\">✅ Lợi &iacute;ch khi lắp đặt</h3>\r\n<ul data-start=\"1309\" data-end=\"1469\">\r\n<li data-start=\"1309\" data-end=\"1346\">\r\n<p data-start=\"1311\" data-end=\"1346\">Giảm điểm m&ugrave; khi vận h&agrave;nh xe n&acirc;ng</p>\r\n</li>\r\n<li data-start=\"1347\" data-end=\"1376\">\r\n<p data-start=\"1349\" data-end=\"1376\">N&acirc;ng cao an to&agrave;n lao động</p>\r\n</li>\r\n<li data-start=\"1377\" data-end=\"1417\">\r\n<p data-start=\"1379\" data-end=\"1417\">Hạn chế va chạm trong kh&ocirc;ng gian hẹp</p>\r\n</li>\r\n<li data-start=\"1418\" data-end=\"1469\">\r\n<p data-start=\"1420\" data-end=\"1469\">Ph&ugrave; hợp kho logistics, nh&agrave; m&aacute;y, khu c&ocirc;ng nghiệp</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1471\" data-end=\"1474\">\r\n<p data-start=\"1476\" data-end=\"1574\">📌 <strong data-start=\"1479\" data-end=\"1532\">Ph&acirc;n phối &amp; lắp đặt bởi C&Ocirc;NG TY TNHH KỸ THUẬT NMT</strong><br data-start=\"1532\" data-end=\"1535\">🔧 Tư vấn &ndash; lắp đặt &ndash; bảo h&agrave;nh kỹ thuật</p>','photos/1/z7494932768138_23bc2e94091d0464cd81f7501b2ffb38.jpg','Mới',NULL,NULL,1,0,4,1,NULL,NULL,'2026-01-27 04:35:06','2026-02-02 09:10:34',NULL),(5,2,'Bộ hạn chế tốc độ xe nâng và máy công trình','he-thong-luu-tru-50kwh',NULL,'Bộ hạn chế tốc độ xe nâng và máy công trình – Giải pháp an toàn cho kho xưởng','<p data-start=\"200\" data-end=\"415\"><strong data-start=\"200\" data-end=\"229\">Bộ hạn chế tốc độ xe n&acirc;ng</strong> l&agrave; thiết bị chuy&ecirc;n dụng gi&uacute;p <strong data-start=\"259\" data-end=\"308\">gi&aacute;m s&aacute;t, cảnh b&aacute;o v&agrave; giới hạn tốc độ xe n&acirc;ng</strong> trong qu&aacute; tr&igrave;nh vận h&agrave;nh, nhằm <strong data-start=\"340\" data-end=\"365\">giảm tai nạn lao động</strong>, bảo vệ người v&agrave; h&agrave;ng h&oacute;a tại kho xưởng, nh&agrave; m&aacute;y.</p>\r\n<p data-start=\"417\" data-end=\"669\">Thiết bị sử dụng <strong data-start=\"434\" data-end=\"463\">cảm biến tốc độ kh&ocirc;ng d&acirc;y</strong>, hiển thị tốc độ trực tiếp tr&ecirc;n m&agrave;n h&igrave;nh LED, kết hợp <strong data-start=\"518\" data-end=\"572\">cảnh b&aacute;o đ&egrave;n &ndash; c&ograve;i khi xe vượt qu&aacute; tốc độ cho ph&eacute;p</strong>. Hệ thống hỗ trợ <strong data-start=\"590\" data-end=\"636\">giới hạn tốc độ bằng ga điện tử hoặc ga cơ</strong>, ph&ugrave; hợp với nhiều loại xe n&acirc;ng.</p>\r\n<hr data-start=\"671\" data-end=\"674\">\r\n<h3 data-start=\"676\" data-end=\"698\">🔹 Ưu điểm nổi bật</h3>\r\n<ul data-start=\"699\" data-end=\"983\">\r\n<li data-start=\"699\" data-end=\"753\">\r\n<p data-start=\"701\" data-end=\"753\">Gi&aacute;m s&aacute;t v&agrave; <strong data-start=\"713\" data-end=\"753\">giới hạn tốc độ xe n&acirc;ng theo c&agrave;i đặt</strong></p>\r\n</li>\r\n<li data-start=\"754\" data-end=\"803\">\r\n<p data-start=\"756\" data-end=\"803\"><strong data-start=\"756\" data-end=\"779\">Cảnh b&aacute;o c&ograve;i v&agrave; đ&egrave;n</strong> khi vượt tốc độ an to&agrave;n</p>\r\n</li>\r\n<li data-start=\"804\" data-end=\"854\">\r\n<p data-start=\"806\" data-end=\"854\"><strong data-start=\"806\" data-end=\"835\">Cảm biến tốc độ kh&ocirc;ng d&acirc;y</strong>, lắp đặt nhanh gọn</p>\r\n</li>\r\n<li data-start=\"855\" data-end=\"887\">\r\n<p data-start=\"857\" data-end=\"887\">Hỗ trợ <strong data-start=\"864\" data-end=\"887\">ga điện tử v&agrave; ga cơ</strong></p>\r\n</li>\r\n<li data-start=\"888\" data-end=\"939\">\r\n<p data-start=\"890\" data-end=\"939\"><strong data-start=\"890\" data-end=\"918\">C&agrave;i đặt nhiều mức tốc độ</strong> ph&ugrave; hợp từng khu vực</p>\r\n</li>\r\n<li data-start=\"940\" data-end=\"983\">\r\n<p data-start=\"942\" data-end=\"983\">Hoạt động ổn định, độ bền cao, dễ bảo tr&igrave;</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"985\" data-end=\"988\">\r\n<h3 data-start=\"990\" data-end=\"1021\">🔹 Th&ocirc;ng số kỹ thuật cơ bản</h3>\r\n<ul data-start=\"1022\" data-end=\"1247\">\r\n<li data-start=\"1022\" data-end=\"1056\">\r\n<p data-start=\"1024\" data-end=\"1056\">Điện &aacute;p hoạt động: <strong data-start=\"1043\" data-end=\"1056\">DC 12&ndash;48V</strong></p>\r\n</li>\r\n<li data-start=\"1057\" data-end=\"1085\">\r\n<p data-start=\"1059\" data-end=\"1085\">Hiển thị: <strong data-start=\"1069\" data-end=\"1085\">M&agrave;n h&igrave;nh LED</strong></p>\r\n</li>\r\n<li data-start=\"1086\" data-end=\"1118\">\r\n<p data-start=\"1088\" data-end=\"1118\">Cảm biến tốc độ: <strong data-start=\"1105\" data-end=\"1118\">Kh&ocirc;ng d&acirc;y</strong></p>\r\n</li>\r\n<li data-start=\"1119\" data-end=\"1158\">\r\n<p data-start=\"1121\" data-end=\"1158\">Cảnh b&aacute;o: <strong data-start=\"1131\" data-end=\"1158\">Đ&egrave;n xoay + c&ograve;i &acirc;m thanh</strong></p>\r\n</li>\r\n<li data-start=\"1159\" data-end=\"1202\">\r\n<p data-start=\"1161\" data-end=\"1202\">Chức năng: <strong data-start=\"1172\" data-end=\"1202\">Cảnh b&aacute;o &amp; giới hạn tốc độ</strong></p>\r\n</li>\r\n<li data-start=\"1203\" data-end=\"1247\">\r\n<p data-start=\"1205\" data-end=\"1247\">Tương th&iacute;ch: <strong data-start=\"1218\" data-end=\"1247\">Xe n&acirc;ng điện, xe n&acirc;ng dầu</strong></p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1249\" data-end=\"1252\">\r\n<h3 data-start=\"1254\" data-end=\"1277\">🔹 Ứng dụng thực tế</h3>\r\n<ul data-start=\"1278\" data-end=\"1488\">\r\n<li data-start=\"1278\" data-end=\"1307\">\r\n<p data-start=\"1280\" data-end=\"1307\">Kho b&atilde;i, nh&agrave; xưởng sản xuất</p>\r\n</li>\r\n<li data-start=\"1308\" data-end=\"1348\">\r\n<p data-start=\"1310\" data-end=\"1348\">Khu vực c&oacute; người qua lại, lối đi chung</p>\r\n</li>\r\n<li data-start=\"1349\" data-end=\"1375\">\r\n<p data-start=\"1351\" data-end=\"1375\">Nh&agrave; m&aacute;y, khu c&ocirc;ng nghiệp</p>\r\n</li>\r\n<li data-start=\"1376\" data-end=\"1422\">\r\n<p data-start=\"1378\" data-end=\"1422\">Doanh nghiệp cần <strong data-start=\"1395\" data-end=\"1422\">quản l&yacute; an to&agrave;n xe n&acirc;ng</strong></p>\r\n</li>\r\n<li data-start=\"1423\" data-end=\"1488\">\r\n<p data-start=\"1425\" data-end=\"1488\">Lắp mới hoặc <strong data-start=\"1438\" data-end=\"1488\">n&acirc;ng cấp hệ thống an to&agrave;n cho xe n&acirc;ng hiện hữu</strong></p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1490\" data-end=\"1493\">\r\n<p data-start=\"1495\" data-end=\"1606\">👉 <strong data-start=\"1498\" data-end=\"1547\">NMT AUTO &ndash; Đơn vị ph&acirc;n phối &amp; hỗ trợ kỹ thuật</strong><br data-start=\"1547\" data-end=\"1550\">🌐 <strong data-start=\"1553\" data-end=\"1575\"><a class=\"decorated-link\" href=\"http://www.nmtauto.com.vn\" target=\"_new\" rel=\"noopener\" data-start=\"1555\" data-end=\"1573\">www.nmtauto.com.vn</a></strong> | 📞 <strong data-start=\"1581\" data-end=\"1606\">Hotline: 0385 686 223</strong></p>','photos/1/a00c3fd2-ca83-4c74-ad7b-be4521968333.png',NULL,NULL,NULL,1,0,5,1,NULL,NULL,'2026-01-27 04:35:06','2026-02-02 07:29:21',NULL),(6,2,'Camera AI 360 cho Xe Nâng & Máy Công Trình','camera-ai-nhan-dien-khuon-mat',NULL,'Giới thiệu Camera AI cho Xe Nâng & Máy Công Trình – Giải pháp thông minh từ NMT','<p data-start=\"394\" data-end=\"674\">Trong m&ocirc;i trường c&ocirc;ng nghiệp ng&agrave;y c&agrave;ng phức tạp, an to&agrave;n vận h&agrave;nh v&agrave; hiệu quả lao động l&agrave; hai yếu tố sống c&ograve;n. <strong data-start=\"505\" data-end=\"544\">Hệ thống Camera AI do NMT ph&acirc;n phối</strong> l&agrave; giải ph&aacute;p gi&aacute;m s&aacute;t &ndash; hỗ trợ l&aacute;i &ndash; cảnh b&aacute;o th&ocirc;ng minh d&agrave;nh ri&ecirc;ng cho <strong data-start=\"617\" data-end=\"663\">xe n&acirc;ng, m&aacute;y x&uacute;c, m&aacute;y ủi, cần cẩu, loader&hellip;</strong>, mang tới:</p>\r\n<p data-start=\"676\" data-end=\"889\">✔️ <strong data-start=\"679\" data-end=\"724\">Tầm nh&igrave;n 360&deg; quanh xe &amp; khu vực l&agrave;m việc</strong><br data-start=\"724\" data-end=\"727\">✔️ <strong data-start=\"730\" data-end=\"780\">Nhận dạng đối tượng bằng tr&iacute; tuệ nh&acirc;n tạo (AI)</strong><br data-start=\"780\" data-end=\"783\">✔️ <strong data-start=\"786\" data-end=\"839\">Cảnh b&aacute;o sớm nguy cơ va chạm &ndash; người/xe &ndash; điểm m&ugrave;</strong><br data-start=\"839\" data-end=\"842\">✔️ <strong data-start=\"845\" data-end=\"889\">Tối ưu hiệu suất &amp; bảo vệ t&agrave;i sản đầu tư</strong></p>\r\n<hr data-start=\"891\" data-end=\"894\">\r\n<h2 data-start=\"896\" data-end=\"954\">🎯 <strong data-start=\"902\" data-end=\"954\">Ứng dụng Camera AI tr&ecirc;n xe n&acirc;ng &amp; m&aacute;y c&ocirc;ng tr&igrave;nh</strong></h2>\r\n<h3 data-start=\"956\" data-end=\"984\">📍 1. Tăng cường an to&agrave;n</h3>\r\n<ul data-start=\"985\" data-end=\"1167\">\r\n<li data-start=\"985\" data-end=\"1058\">\r\n<p data-start=\"987\" data-end=\"1058\">📷 Cảnh b&aacute;o người, phương tiện, chướng ngại vật gần khu vực nguy hiểm</p>\r\n</li>\r\n<li data-start=\"1059\" data-end=\"1119\">\r\n<p data-start=\"1061\" data-end=\"1119\">🚨 Hệ thống b&aacute;o &acirc;m thanh &amp; h&igrave;nh ảnh real-time cho l&aacute;i xe</p>\r\n</li>\r\n<li data-start=\"1120\" data-end=\"1167\">\r\n<p data-start=\"1122\" data-end=\"1167\">🧠 AI ph&acirc;n t&iacute;ch chuyển động v&agrave; dự đo&aacute;n rủi ro</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"1169\" data-end=\"1209\">📍 2. Giảm thiểu tai nạn v&agrave; tổn thất</h3>\r\n<ul data-start=\"1210\" data-end=\"1357\">\r\n<li data-start=\"1210\" data-end=\"1254\">\r\n<p data-start=\"1212\" data-end=\"1254\">Giảm điểm m&ugrave; v&ugrave;ng sau v&agrave; hai b&ecirc;n th&acirc;n xe</p>\r\n</li>\r\n<li data-start=\"1255\" data-end=\"1302\">\r\n<p data-start=\"1257\" data-end=\"1302\">Hỗ trợ l&ugrave;i đỗ, quay đầu tr&ecirc;n kh&ocirc;ng gian hẹp</p>\r\n</li>\r\n<li data-start=\"1303\" data-end=\"1357\">\r\n<p data-start=\"1305\" data-end=\"1357\">Ghi lại bằng chứng sự cố phục vụ đ&aacute;nh gi&aacute; v&agrave; đ&agrave;o tạo</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"1359\" data-end=\"1396\">📍 3. N&acirc;ng cao năng suất vận h&agrave;nh</h3>\r\n<ul data-start=\"1397\" data-end=\"1561\">\r\n<li data-start=\"1397\" data-end=\"1457\">\r\n<p data-start=\"1399\" data-end=\"1457\">H&igrave;nh ảnh chất lượng cao, ban ng&agrave;y &amp; ban đ&ecirc;m (hồng ngoại)</p>\r\n</li>\r\n<li data-start=\"1458\" data-end=\"1505\">\r\n<p data-start=\"1460\" data-end=\"1505\">Ghi h&igrave;nh lưu trữ phục vụ kiểm tra hoạt động</p>\r\n</li>\r\n<li data-start=\"1506\" data-end=\"1561\">\r\n<p data-start=\"1508\" data-end=\"1561\">T&iacute;ch hợp với m&agrave;n h&igrave;nh on-board v&agrave; hệ thống telematics</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1563\" data-end=\"1566\">\r\n<h2 data-start=\"1568\" data-end=\"1626\">📦 <strong data-start=\"1574\" data-end=\"1626\">C&aacute;c t&iacute;nh năng nổi bật của hệ thống NMT ph&acirc;n phối</strong></h2>\r\n<p data-start=\"1628\" data-end=\"1757\">✨ <strong data-start=\"1630\" data-end=\"1656\">Nhận dạng đối tượng AI</strong><br data-start=\"1656\" data-end=\"1659\">Nhận diện người đi bộ, xe kh&aacute;c, pallet, vật cản&hellip; với độ ch&iacute;nh x&aacute;c cao, tự ph&acirc;n biệt loại mục ti&ecirc;u.</p>\r\n<p data-start=\"1759\" data-end=\"1944\">✨ <strong data-start=\"1761\" data-end=\"1784\">Cảnh b&aacute;o th&ocirc;ng minh</strong><br data-start=\"1784\" data-end=\"1787\">Cảnh b&aacute;o theo ngữ cảnh vận h&agrave;nh:<br data-start=\"1819\" data-end=\"1822\">🔹 B&aacute;o khi xe tiến/l&ugrave;i cận người<br data-start=\"1854\" data-end=\"1857\">🔹 B&aacute;o khi vật cản gần v&ugrave;ng quay/đỗ<br data-start=\"1892\" data-end=\"1895\">🔹 B&aacute;o vượt tốc độ an to&agrave;n trong khu vực giới hạn</p>\r\n<p data-start=\"1946\" data-end=\"1969\">✨ <strong data-start=\"1948\" data-end=\"1969\">Lắp đặt linh hoạt</strong></p>\r\n<ul data-start=\"1970\" data-end=\"2141\">\r\n<li data-start=\"1970\" data-end=\"2004\">\r\n<p data-start=\"1972\" data-end=\"2004\">Camera g&oacute;c rộng &ndash; 4K / Full-HD</p>\r\n</li>\r\n<li data-start=\"2005\" data-end=\"2061\">\r\n<p data-start=\"2007\" data-end=\"2061\">Ghi h&igrave;nh trước/sau/hai b&ecirc;n &ndash; t&ugrave;y chọn tối ưu theo xe</p>\r\n</li>\r\n<li data-start=\"2062\" data-end=\"2141\">\r\n<p data-start=\"2064\" data-end=\"2141\">Kết nối với m&agrave;n h&igrave;nh t&aacute;p-l&ocirc;, tablet c&ocirc;ng nghiệp, hoặc bộ điều khiển trung t&acirc;m</p>\r\n</li>\r\n</ul>','photos/1/z7324338877952_aa9718dee7b8edcbad02a1ce8183f97a.jpg','Hot',NULL,NULL,1,0,6,1,NULL,NULL,'2026-01-27 04:35:06','2026-02-02 07:30:58',NULL),(7,NULL,'Hộp điều khiển máy xúc Hyundai','phu-tung-xe-nang',NULL,'Hộp điều khiển máy xúc Hyundai HS 80V',NULL,'photos/1/z7495011925995_a038b0ad23356efe1df14f384c708c5f.jpg',NULL,NULL,NULL,0,0,7,1,NULL,NULL,'2026-01-30 02:46:25','2026-02-02 10:12:02',NULL),(8,2,'Camera AI & Đèn Chiếu Vạch An Toàn Xe Nâng – Giảm Tai Nạn Hiệu Quả','camera-ai-den-chieu-vach-an-toan-xe-nang-giam-tai-nan-hieu-qua',NULL,'Camera AI Kết Hợp Đèn Chiếu Vạch – Cảnh Báo An Toàn Thông Minh','<p>Camera AI kết hợp đ&egrave;n chiếu vạch an to&agrave;n l&agrave; giải ph&aacute;p n&acirc;ng cao an to&agrave;n vận h&agrave;nh cho xe n&acirc;ng trong nh&agrave; xưởng, kho b&atilde;i v&agrave; khu vực sản xuất.</p>\r\n<p>Hệ thống t&iacute;ch hợp:<br>&ndash; Camera quan s&aacute;t độ ph&acirc;n giải cao, hiển thị r&otilde; r&agrave;ng tr&ecirc;n m&agrave;n h&igrave;nh 7 inch<br>&ndash; Nhận diện người v&agrave; vật cản xung quanh xe n&acirc;ng<br>&ndash; Đ&egrave;n chiếu vạch an to&agrave;n cảnh b&aacute;o v&ugrave;ng nguy hiểm ph&iacute;a trước v&agrave; xung quanh xe<br>&ndash; C&ograve;i / cảnh b&aacute;o &acirc;m thanh khi ph&aacute;t hiện nguy cơ va chạm</p>\r\n<p>Ưu điểm nổi bật:<br>✔️ Giảm thiểu tai nạn lao động trong kho xưởng &nbsp;<br>✔️ N&acirc;ng cao &yacute; thức an to&agrave;n cho người vận h&agrave;nh v&agrave; c&ocirc;ng nh&acirc;n &nbsp;<br>✔️ Hoạt động ổn định trong m&ocirc;i trường c&ocirc;ng nghiệp, chống nước &ndash; chống bụi &nbsp;<br>✔️ Ph&ugrave; hợp cho xe n&acirc;ng điện, xe n&acirc;ng dầu, m&aacute;y c&ocirc;ng tr&igrave;nh &nbsp;</p>\r\n<p>Ứng dụng:<br>&ndash; Nh&agrave; xưởng sản xuất &nbsp;<br>&ndash; Kho logistics &nbsp;<br>&ndash; Trung t&acirc;m ph&acirc;n phối &nbsp;<br>&ndash; Khu c&ocirc;ng nghiệp &nbsp;</p>\r\n<p>📞 Li&ecirc;n hệ tư vấn &amp; lắp đặt:<br>Hotline: 0385 686 223 &nbsp;<br>Đơn vị cung cấp: NMT AUTO &nbsp;</p>\r\n<p>👉 Đăng k&yacute; k&ecirc;nh để xem th&ecirc;m c&aacute;c giải ph&aacute;p an to&agrave;n xe n&acirc;ng v&agrave; thiết bị c&ocirc;ng nghiệp mới nhất!<a href=\"https://youtu.be/Qteypptdyng\">https://youtu.be/Qteypptdyng</a></p>','photos/1/SP NMT.png',NULL,NULL,NULL,0,0,8,1,NULL,NULL,'2026-02-02 23:43:17','2026-02-02 23:43:17',NULL);
